// mapExif maps exiftool's tag map (the JSON object runExiftool returns) to the
// sources.image-enricher namespace. width/height/format are mapped FIRST so a
// decodable image always yields a non-empty namespace (prevents the R-I5 spurious-
// no_data regression); the optional tags follow and are simply absent when exiftool
// omits them. FileType is lowercased (exiftool emits "JPEG"/"PNG"/...). The
// DateTimeOriginal machine form is normalized to RFC3339 when parseable, else
// carried verbatim. Non-ASCII strings (e.g. a Cyrillic Model) pass through
// untouched (exiftool emits UTF-8 JSON; strings are not re-encoded).
func mapExif(tags map[string]any) map[string]any {
	out := map[string]any{}
	if v, ok := numVal(tags, "ImageWidth"); ok {
		out["width"] = v
	}
	if v, ok := numVal(tags, "ImageHeight"); ok {
		out["height"] = v
	}
	if s, ok := strVal(tags, "FileType"); ok {
		out["format"] = strings.ToLower(s)
	}
	if v, ok := strVal(tags, "Make"); ok {
		out["make"] = v
	}
	if v, ok := strVal(tags, "Model"); ok {
		out["model"] = v
	}
	if v, ok := strVal(tags, "DateTimeOriginal"); ok {
		out["date_taken"] = normalizeExifDate(v)
	}
	if v, ok := numVal(tags, "Orientation"); ok {
		out["orientation"] = v
	}
	if v, ok := numVal(tags, "GPSLatitude"); ok {
		out["gps_lat"] = v
	}
	if v, ok := numVal(tags, "GPSLongitude"); ok {
		out["gps_lon"] = v
	}
	return out
}

// normalizeExifDate parses exiftool's -n DateTimeOriginal ("2024:07:30 14:21:05")
// and emits RFC3339 (UTC, since no timezone tag is selected). An unparseable value
// is carried verbatim rather than dropped (B10 philosophy: do not re-encode).
func normalizeExifDate(raw string) string {
	if t, err := time.Parse(exifDateLayout, raw); err == nil {
		return t.UTC().Format(time.RFC3339)
	}
	return raw
}

// isImageExt reports whether the (already-lowercased, dotted) extension is an
// image extension image-enricher handles. The format hint is derived from the
// extension in Match (imageExts).
func isImageExt(ext string) bool {
	_, ok := imageExts[ext]
	return ok
}

// numVal reads a numeric EXIF tag (exiftool -n emits JSON numbers, which decode
// to float64) from the tag map. Non-numeric values are treated as absent.
func numVal(tags map[string]any, key string) (float64, bool) {
	switch n := tags[key].(type) {
	case float64:
		return n, true
	case int:
		return float64(n), true
	case int64:
		return float64(n), true
	}
	return 0, false
}

// strVal reads a string EXIF tag from the tag map. Non-string values are treated
// as absent (exiftool emits UTF-8 strings verbatim).
func strVal(tags map[string]any, key string) (string, bool) {
	if s, ok := tags[key].(string); ok {
		return s, true
	}
	return "", false
}

// provenanceHints builds the per-field provenance hint map the core merges over
// its authoritative _provenance stamp. Each field names image-enricher + its
// version + the fetch time. Confidence is left to the core (it uses the Match
// confidence when the hint omits it). Verbatim mirror of parser.go:141-153.
